function normalizeIssuerKey(s: string): string {
  return s
    .toLowerCase()
    .normalize("NFD")
    .replace(/\p{M}/gu, "")
    .replace(/[^a-z0-9\s]/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

const SAFELIST_KEYS = new Set(ISSUER_SAFELIST.map(normalizeIssuerKey));

/** True when a display label matches a safelist entry (exact normalized key). */
export function isSafelistIssuer(issuer: string): boolean {
  return SAFELIST_KEYS.has(normalizeIssuerKey(issuer));
}

/**
 * Best-effort match: exact key, or safelist entry contains / is contained by query.
 * Used when users type shorthand (e.g. "Chase" vs "JPMorgan Chase Bank, N.A.").
 */
export function matchesSafelistIssuer(query: string): boolean {
  return findBestSafelistIssuerInText(query) !== null;
}

function scoreSafelistPair(queryNorm: string, entryNorm: string): number {
  if (!queryNorm || !entryNorm) return 0;
  if (queryNorm === entryNorm) return 10_000 + entryNorm.length;
  if (queryNorm.includes(entryNorm)) return 5_000 + entryNorm.length;
  if (entryNorm.includes(queryNorm) && queryNorm.length >= 4) {
    return 4_000 + queryNorm.length;
  }
  const qTokens = queryNorm.split(" ").filter((t) => t.length >= 3);
  const eTokens = entryNorm.split(" ").filter((t) => t.length >= 3);
  if (qTokens.length === 0 || eTokens.length === 0) return 0;
  let matched = 0;
  for (const t of qTokens) {
    if (eTokens.some((et) => et === t || et.includes(t) || t.includes(et))) {
      matched++;
    }
  }
  return matched > 0 ? matched * 200 + Math.min(qTokens.length, eTokens.length) : 0;
}

/** Longest / strongest safelist label found inside free-text user input. */
export function findBestSafelistIssuerInText(raw: string): string | null {
  const q = normalizeIssuerKey(raw);
  if (q.length < 2) return null;

  let best: { entry: string; score: number } | null = null;
  for (const entry of ISSUER_SAFELIST) {
    const k = normalizeIssuerKey(entry);
    const score = scoreSafelistPair(q, k);
    if (!best || score > best.score) {
      best = { entry, score };
    }
  }
  if (!best || best.score < 200) return null;
  return best.entry;
}

export function stripSafelistIssuerFromQuery(
  raw: string,
  safelistIssuer: string,
): string {
  const q = raw.trim();
  const idx = q.toLowerCase().indexOf(safelistIssuer.toLowerCase().slice(0, 12));
  if (idx >= 0) {
    const rest = `${q.slice(0, idx)} ${q.slice(idx + safelistIssuer.length)}`.trim();
    if (rest.length >= 2) return rest;
  }
  const qNorm = normalizeIssuerKey(q);
  const iNorm = normalizeIssuerKey(safelistIssuer);
  for (const token of iNorm.split(" ").filter((t) => t.length >= 4)) {
    const re = new RegExp(`\\b${token}\\b`, "i");
    const cleaned = q.replace(re, " ").replace(/\s+/g, " ").trim();
    if (cleaned.length >= 2) return cleaned;
  }
  return qNorm.length >= 2 ? q : safelistIssuer;
}
